import 'package:flutter/material.dart';
import 'package:convex_bottom_bar/convex_bottom_bar.dart';

class ConvexNav extends StatefulWidget {
  const ConvexNav({super.key});

  @override
  State<ConvexNav> createState() => _ConvexNavState();
}

class _ConvexNavState extends State<ConvexNav> {
  int index = 0;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: IndexedStack(
        index: index,
        children: const [
          Center(child: Text('홈')),
          Center(child: Text('검색')),
          Center(child: Text('프로필')),
        ],
      ),
      bottomNavigationBar: ConvexAppBar(
        items: const [
          TabItem(icon: Icons.home, title: '홈'),
          TabItem(icon: Icons.search, title: '검색'),
          TabItem(icon: Icons.person, title: '프로필'),
        ],
        initialActiveIndex: index,
        onTap: (i) => setState(() => index = i),
      ),
    );
  }
}

